  const exerciseSeeds={胸:['卧推','上斜哑铃卧推','俯卧撑','哑铃飞鸟'],肩:['推举','哑铃侧平举','俯身反向飞鸟'],背:['坐姿划船','哑铃划船','引体向上'],腿:['深蹲','硬拉','弓步蹲','壶铃高脚杯深蹲'],臂:['哑铃弯举','杠铃弯举','臂屈伸'],腹:['卷腹','仰卧举腿','俄罗斯转体']};
