  function workoutPage(){const d=db.draft;if(!d){route='train';return trainPage();}const a=d.active;const last=a?db.strength.filter(r=>r.name===a.name&&r.equipment===a.equipment&&r.date<=d.date).sort((x,y)=>x.date.localeCompare(y.date)||x.updatedAt.localeCompare(y.updatedAt)).at(-1):null;return `<div class="workout-top row between"><div><small>${d.date} · ${d.mode==='big3'?tr("三大项"):tr(d.muscle)+tr("部训练")}</small><h2>${a?esc(exerciseLabel(a.name)):tr("准备好下一个动作")}</h2><small>${tr("{0} 个动作已完成{1}", d.finished.length, a?' · '+a.sets.length+tr(" 组已记录"):'')}</small></div><span class="badge" style="background:#e2edcd;color:#315b44">${tr("运动中")}</span></div><div class="page-grid"><section class="card full">${a?`<div class="card-title"><h2>${esc(exerciseLabel(a.name))} <span class="badge">${esc(tr(a.equipment))}</span></h2><button class="text-btn" data-act="history">${tr("历史")}</button></div><p class="tip">${a.equipment==='杠铃'?tr("本次输入片重，另加杆重 {0} kg。", a.barWeight):tr("按额外负重或器械总重记录；哑铃按总重。")}${last?tr("上次记录：")+last.date+'。':tr("还没有这个动作的历史记录。")}</p><div class="set-header"><span>${tr("组")}</span><span>${tr("上次")}</span><span>${tr("输入 kg")}</span><span>${tr("次数")}</span><span>${tr("编辑")}</span></div>${a.sets.map((s,i)=>`<div class="set-row"><span>${s.warmup?tr("热"):i+1}</span><span class="previous">${last?.sets[i]?`${fmt(last.sets[i].weight)} × ${last.sets[i].reps}`:'—'}</span><strong>${fmt(s.weight)}</strong><strong>${s.reps}</strong><button data-edit-set="${i}" aria-label="${tr("编辑第 {0} 组", i+1)}">${icon('check')}</button></div>`).join('')||`<p class="tip">${tr("还没有完成组，填写下面的数据开始记录。")}</p>`}<form id="set-form" class="set-input"><div class="form-grid">${field('weight',a.equipment==='杠铃'?tr("两侧片重合计"):tr("器械总重 / 额外负重"),a.nextWeight??a.sets.at(-1)?.weight??0,{unit:'kg',max:1000})}${field('reps',tr("本组次数"),'',{unit:tr("次"),min:1,max:1000,step:'1'})}</div><div class="row between wrap space-top"><label class="check-field"><input name="warmup" type="checkbox">${tr("热身组")}</label><small>${tr("只记录实际完成的组")}</small></div><div class="form-error" id="set-error" role="alert"></div><button type="submit" class="btn wide space-top">${tr("{0}记录一组", icon('check'))}</button></form><div class="timer"><label class="check-field"><input id="rest-enabled" type="checkbox" ${restEnabled?'checked':''}>${tr("组间休息")}</label><strong id="timer-text">${timerEnd?'':'01:30'}</strong><button data-act="timer-reset">${tr("重计")}</button><button data-act="timer-skip">${tr("跳过")}</button></div><div class="form-actions"><button class="btn ghost" data-act="note">${tr("动作备注")}</button><button class="btn" data-act="finish-action" ${!a.sets.length?'disabled':''}>${tr("完成动作")}</button></div>`:`${empty(tr("本次训练由你安排"),tr("选择动作，记录每一组真实完成。"),'weight')}<button class="btn wide space-top" data-act="exercise">${tr("{0}添加下一个动作", icon('plus'))}</button>`}</section>${d.finished.length?`<section class="card full"><h2>${tr("本次已完成")}</h2>${d.finished.map(r=>`<div class="record-row"><span><span class="title">${esc(recordName(r))}</span><span class="detail" style="display:block">${tr("{0} · {1} 正式组 / {2} 热身组", esc(tr(r.equipment)), r.sets.filter(s=>!s.warmup).length, r.sets.filter(s=>s.warmup).length)}</span></span><strong>${tr("{0} 组", r.sets.length)}</strong></div>`).join('')}</section>`:''}<div class="full row wrap between"><button class="btn danger" data-act="discard-workout">${tr("放弃本次训练")}</button><button class="btn" data-act="finish-workout" ${!d.finished.length&&!a?.sets.length?'disabled':''}>${tr("结束本次训练")}</button></div></div>`;}
  function bindSetForm(){const form=$('#set-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();try{const fd=new FormData(form),s={weight:val(fd,'weight'),reps:val(fd,'reps'),warmup:fd.get('warmup')==='on',at:new Date().toISOString()};const a=clone(db.draft.active);a.sets.push(s);F.validateRecord('strength',a);commit(next=>{next.draft.active=a;next.draft.active.nextWeight=s.weight;});if(restEnabled)timerEnd=Date.now()+90000;render();toast(tr("第 {0} 组已保存",a.sets.length));}catch(err){$('#set-error').textContent=tr(err.message);}};$('#rest-enabled').onchange=e=>{restEnabled=e.target.checked;if(!restEnabled)timerEnd=0;tick();};}
