    const preview=()=>{const fd=new FormData($('#record-form')),minutes=opt(fd,'sessionMinutes'),e=E.strength(db,d.date,minutes,String(fd.get('sessionEffort')));$('#strength-energy-preview').textContent=e?tr("本场额外消耗约 {0} kcal，采用当日体重 {1} kg、MET {2}；按整场计一次。", fmt(e.netKcal), fmt(e.weight), e.met):(minutes?tr(E.reason(db,d.date)):tr("未填时长，本场不计入消耗估算。"));};$('#record-form').addEventListener('input',preview);$('#record-form').addEventListener('change',preview);preview();
    bindForm(fd=>{const minutes=opt(fd,'sessionMinutes'),effort=String(fd.get('sessionEffort')),energy=E.strength(db,d.date,minutes,effort);commit(next=>{const draft=next.draft;if(draft.active?.sets.length){draft.active.updatedAt=new Date().toISOString();draft.finished.push(draft.active);}next.strength.push(...draft.finished);next.sessions.push({id:draft.id,date:draft.date,minutes,effort,energy});if(draft.planId&&draft.date===F.localDate()){const p=next.plans.find(p=>p.id===draft.planId);if(p)p.cursor=(draft.dayIndex+1)%p.days.length;}next.draft=null;});selected=d.date;month=selected.slice(0,7);route='calendar';timerEnd=0;close();render();toast(tr("本次训练已保存到日历"));});
